//! Device-free media for the isolated paired realtime route.
//!
//! Encoded bytes are generated by this test process's linked software codecs.
//! They are transport expectations, not cross-version bitstream goldens. The
//! caller must compare the received payloads before running the lossy decode
//! checks below. This module does not capture, render, or play media.

use allmystuff_audio::codec::{OpusDecoder, OpusStream};
use allmystuff_audio::{OPUS_FRAME_SAMPLES, OPUS_RATE};
use openh264::decoder::{Decoder, DecoderConfig, Flush};
use openh264::encoder::{Encoder, EncoderConfig, FrameRate, FrameType};
use openh264::formats::{YUVBuffer, YUVSource};

pub const VIDEO_WIDTH: usize = 64;
pub const VIDEO_HEIGHT: usize = 64;
pub const VIDEO_FRAMES: usize = 3;
pub const VIDEO_DURATION_US: u64 = 40_000;
pub const AUDIO_PACKETS: usize = 6;
pub const AUDIO_DURATION_US: u64 = 20_000;
const FIRST_TS_US: u64 = 1_000_000;
const TONE_PERIOD: usize = 48; // 48 kHz / 48 = 1 kHz.
const TONE_AMPLITUDE: f64 = 10_000.0;

#[derive(Clone, Debug)]
pub struct EncodedVideo {
    /// Source provenance; the candidate wire does not transmit this field.
    pub ts_us: u64,
    /// Encoder classification, not a claim about a received RTP marker bit.
    pub key: bool,
    pub width: usize,
    pub height: usize,
    pub duration_us: u64,
    pub data: Vec<u8>,
}

#[derive(Clone, Debug)]
pub struct EncodedAudio {
    /// Source provenance; compare received relative clocks in the route adapter.
    pub ts_us: u64,
    pub duration_us: u64,
    pub data: Vec<u8>,
}

#[derive(Clone, Debug)]
pub struct CodecFixture {
    pub video: Vec<EncodedVideo>,
    pub audio: Vec<EncodedAudio>,
}

/// Three ordered pictures and six complete Opus packets; no hardware selection.
pub fn generated_media() -> CodecFixture {
    let mut encoder = Encoder::with_api_config(
        openh264::OpenH264API::from_source(),
        EncoderConfig::new()
            .skip_frames(false)
            .num_threads(1)
            .max_frame_rate(FrameRate::from_hz(25.0)),
    )
    .expect("initialize source OpenH264 encoder");
    let mut video = Vec::with_capacity(VIDEO_FRAMES);
    for frame in 0..VIDEO_FRAMES {
        // A fresh permutation per picture exposes an order/repeated-frame error.
        // Direct I420 avoids color-conversion rounding in the known input.
        let mut i420 = vec![128; VIDEO_WIDTH * VIDEO_HEIGHT * 3 / 2];
        for y in 0..VIDEO_HEIGHT {
            for x in 0..VIDEO_WIDTH {
                i420[y * VIDEO_WIDTH + x] = expected_luma(frame, x, y);
            }
        }
        let yuv = YUVBuffer::from_vec(i420, VIDEO_WIDTH, VIDEO_HEIGHT);
        let encoded = encoder.encode(&yuv).expect("encode synthetic H264 picture");
        let key = matches!(encoded.frame_type(), FrameType::IDR | FrameType::I);
        let data = encoded.to_vec();
        assert!(!data.is_empty(), "each synthetic picture emits an AU");
        let nals = annex_b_nal_payloads(&data);
        assert!(
            nals.iter().any(|nal| matches!(nal[0] & 0x1f, 1 | 5)),
            "AU contains a coded picture, not just parameter sets"
        );
        if frame == 0 {
            assert!(key, "a fresh H264 encoder must provide a decode entry");
            for kind in [7, 8, 5] {
                assert!(
                    nals.iter().any(|nal| nal[0] & 0x1f == kind),
                    "initial AU carries SPS, PPS and IDR (missing {kind})"
                );
            }
        }
        video.push(EncodedVideo {
            ts_us: FIRST_TS_US + frame as u64 * VIDEO_DURATION_US,
            key,
            width: VIDEO_WIDTH,
            height: VIDEO_HEIGHT,
            duration_us: VIDEO_DURATION_US,
            data,
        });
    }

    let mut encoder = OpusStream::new().expect("initialize software Opus encoder");
    let pcm: Vec<i16> = (0..OPUS_FRAME_SAMPLES * AUDIO_PACKETS)
        .map(|sample| (TONE_AMPLITUDE * tone_angle(sample).sin()).round() as i16)
        .collect();
    let mut packets = Vec::with_capacity(AUDIO_PACKETS);
    // Exercise the real stream chunker with non-20-ms pushes. Five 24-ms
    // buffers still produce six exact 20-ms packets with no remainder.
    for part in pcm.chunks(OPUS_FRAME_SAMPLES * 6 / 5) {
        encoder.push(part, OPUS_RATE, |packet| packets.push(packet));
    }
    assert_eq!(packets.len(), AUDIO_PACKETS, "120 ms of complete audio");
    let audio = packets
        .into_iter()
        .enumerate()
        .map(|(index, data)| {
            assert!(!data.is_empty(), "encoded Opus packet is not PLC");
            EncodedAudio {
                ts_us: FIRST_TS_US + index as u64 * AUDIO_DURATION_US,
                duration_us: AUDIO_DURATION_US,
                data,
            }
        })
        .collect();
    CodecFixture { video, audio }
}

/// Exact NAL bytes excluding only the Annex-B delimiter (three or four bytes).
///
/// Use this on both sent AUs and received Annex-B units before decoding. A
/// profile that emits one NAL per unit may change unit/delimiter boundaries;
/// the ordered NAL payloads must remain byte-identical. Nothing is filtered,
/// reordered, deduplicated or stripped from inside a NAL.
pub fn annex_b_nal_payloads(data: &[u8]) -> Vec<Vec<u8>> {
    let mut starts = Vec::new();
    let mut at = 0;
    while at + 3 <= data.len() {
        let prefix = if data[at..].starts_with(&[0, 0, 0, 1]) {
            4
        } else if data[at..].starts_with(&[0, 0, 1]) {
            3
        } else {
            at += 1;
            continue;
        };
        starts.push((at, at + prefix));
        at += prefix;
    }
    assert_eq!(
        starts.first().map(|&(start, _)| start),
        Some(0),
        "expected Annex-B prefix at the start of every nonempty video unit"
    );
    starts
        .iter()
        .enumerate()
        .map(|(index, &(_, payload))| {
            let end = starts.get(index + 1).map_or(data.len(), |&(start, _)| start);
            assert!(payload < end, "empty H264 NAL is not a picture fixture");
            let nal = &data[payload..end];
            assert_eq!(nal[0] & 0x80, 0, "H264 forbidden_zero_bit");
            nal.to_vec()
        })
        .collect()
}

/// Software-decode received Annex-B units, including per-NAL ingress units.
/// The route adapter owns payload equality and received RTP metadata checks.
pub fn assert_decoded_video(units: &[Vec<u8>]) {
    assert!(!units.is_empty(), "no received H264 units");
    let mut decoder = Decoder::with_api_config(
        openh264::OpenH264API::from_source(),
        DecoderConfig::new().flush_after_decode(Flush::NoFlush),
    )
    .expect("initialize source OpenH264 decoder");
    let mut pictures = 0;
    for unit in units {
        assert!(!unit.is_empty(), "empty unit cannot stand in for a received AU");
        if let Some(yuv) = decoder.decode(unit).expect("decode received H264 unit") {
            assert_picture(&yuv, pictures);
            pictures += 1;
        }
    }
    for yuv in decoder.flush_remaining().expect("flush final H264 picture") {
        assert_picture(&yuv, pictures);
        pictures += 1;
    }
    assert_eq!(pictures, VIDEO_FRAMES, "every ordered picture was decoded");
}

/// Stateful software Opus decode, exact duration and known-tone properties.
pub fn assert_decoded_audio(packets: &[Vec<u8>]) {
    assert_eq!(packets.len(), AUDIO_PACKETS, "all audio packets arrived");
    let mut decoder = OpusDecoder::new().expect("initialize software Opus decoder");
    let mut decoded = Vec::with_capacity(OPUS_FRAME_SAMPLES * AUDIO_PACKETS);
    for packet in packets {
        assert!(!packet.is_empty(), "do not substitute PLC for a received packet");
        let mut pcm = [0; OPUS_FRAME_SAMPLES];
        let count = decoder.decode(packet, &mut pcm).expect("decode received Opus");
        assert_eq!(count, OPUS_FRAME_SAMPLES, "one packet decodes to 20 ms");
        decoded.extend_from_slice(&pcm);
    }

    // Exclude the first 20 ms from signal-quality checks for encoder lookahead
    // and startup, but include it above in the exact decoded sample count.
    // The remaining 100 ms contains 100 complete periods regardless of phase.
    let steady = &decoded[OPUS_FRAME_SAMPLES..];
    let n = steady.len() as f64;
    let energy: f64 = steady.iter().map(|&s| f64::from(s).powi(2)).sum();
    let rms = (energy / n).sqrt();
    // Source RMS is 10000/sqrt(2) ~=7071. Broad lossy-codec tolerance retains
    // an audible non-clipped signal; silence/noise/wrong frequency still fail.
    assert!((4_500.0..9_500.0).contains(&rms), "decoded tone RMS {rms}");
    let dc = steady.iter().map(|&s| f64::from(s)).sum::<f64>() / n;
    assert!(dc.abs() < 500.0, "unexpected decoded DC level {dc}");
    let (sin, cos) = steady.iter().enumerate().fold((0.0, 0.0), |(s, c), (i, &v)| {
        let angle = tone_angle(i);
        (s + f64::from(v) * angle.sin(), c + f64::from(v) * angle.cos())
    });
    // Phase-independent projection onto the known 1-kHz sine/cosine pair.
    // At least 90% of decoded energy must be in the transmitted tone; this
    // checks useful content rather than merely accepting nonzero PCM.
    let tone_energy_fraction = 2.0 * (sin * sin + cos * cos) / (n * energy);
    assert!(
        tone_energy_fraction >= 0.90,
        "decoded 1-kHz energy fraction {tone_energy_fraction}"
    );
}

fn tone_angle(sample: usize) -> f64 {
    std::f64::consts::TAU * (sample % TONE_PERIOD) as f64 / TONE_PERIOD as f64
}

fn expected_luma(frame: usize, x: usize, y: usize) -> u8 {
    let quadrant = usize::from(x >= VIDEO_WIDTH / 2) + 2 * usize::from(y >= VIDEO_HEIGHT / 2);
    [40, 100, 180, 220][(quadrant + frame) % 4]
}

fn assert_picture(yuv: &impl YUVSource, frame: usize) {
    assert!(frame < VIDEO_FRAMES, "unexpected extra decoded picture");
    assert_eq!(yuv.dimensions(), (VIDEO_WIDTH, VIDEO_HEIGHT));
    let (y_stride, u_stride, v_stride) = yuv.strides();
    for row in 0..2 {
        for column in 0..2 {
            // Stay four pixels away from block/quadrant boundaries; quantizer
            // and deblocking differences are allowed at the lossy edges.
            let x0 = column * VIDEO_WIDTH / 2 + 4;
            let x1 = (column + 1) * VIDEO_WIDTH / 2 - 4;
            let y0 = row * VIDEO_HEIGHT / 2 + 4;
            let y1 = (row + 1) * VIDEO_HEIGHT / 2 - 4;
            let expected = expected_luma(frame, x0, y0);
            let mut error = 0_u64;
            for y in y0..y1 {
                for x in x0..x1 {
                    error += u64::from(yuv.y()[y * y_stride + x].abs_diff(expected));
                }
            }
            let mean_error = error as f64 / ((x1 - x0) * (y1 - y0)) as f64;
            assert!(
                mean_error <= 12.0,
                "picture {frame}, quadrant ({column},{row}), mean luma error {mean_error}"
            );
        }
    }
    for (plane, stride) in [(yuv.u(), u_stride), (yuv.v(), v_stride)] {
        let mut error = 0_u64;
        for y in 0..VIDEO_HEIGHT / 2 {
            for x in 0..VIDEO_WIDTH / 2 {
                error += u64::from(plane[y * stride + x].abs_diff(128));
            }
        }
        let mean_error = error as f64 / (VIDEO_WIDTH * VIDEO_HEIGHT / 4) as f64;
        assert!(mean_error <= 12.0, "neutral chroma mean error {mean_error}");
    }
}
